{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Assign observed items cumulative prefix positions and padding position zero across all four category models. This tests position alignment between training prefixes and inference histories while retaining maxlen 64, causal convolutions, four-state 0.8/0.2 readout, embedding shapes, scoring, loss and optimizer. Record and validate the position convention in the generated predictor.",
      "edits": [
        {
          "find": "        pos = torch.arange(length, device=seq.device).unsqueeze(0).expand(batch, -1) + 1\n        pos = pos * (seq != 0).long()",
          "replace": "        pos = seq.ne(0).long().cumsum(dim=1)\n        pos = pos * seq.ne(0).long()"
        },
        {
          "find": "            \"sequence_readout\": \"causal_recent4_blend_0.2\",",
          "replace": "            \"sequence_readout\": \"causal_recent4_blend_0.2\",\n            \"position_encoding\": \"observed_prefix_cumsum\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"causal_recent4_blend_0.2\":\n            raise RuntimeError(f\"Incompatible sequence readout metadata for {ds}\")",
          "replace": "        if meta.get(\"sequence_readout\") != \"causal_recent4_blend_0.2\":\n            raise RuntimeError(f\"Incompatible sequence readout metadata for {ds}\")\n        if meta.get(\"position_encoding\") != \"observed_prefix_cumsum\":\n            raise RuntimeError(f\"Incompatible position encoding metadata for {ds}\")"
        }
      ]
    }
  ],
  "change_summary": "Use cumulative observed-prefix position IDs for all four NextItNet category models and synchronize predictor metadata validation."
}
